    class daditu extends Laya.Script {
        constructor() {
            super();
            this.intType = 1000;
            this.numType = 1000;
            this.strType = "hello laya";
            this.boolType = true;
        }
        onEnable() {
            Laya.SoundManager.stopMusic();
            zhucaidan.gkzikg = true;
            this.time = 0;
            this.cc = this.owner.getChildByName("cc");
            this.cc.alpha = 0;
            this.cc.on(Laya.Event.COMPLETE, this, this.tiao);
        }
        onUpdate() {
            this.time++;
            if (this.time == 120) {
                this.cc.play();
                Laya.SoundManager.playSound("sound/zc.mp3");
            }
            if (this.time > 120) {
                if (this.cc.alpha < 1) {
                    this.cc.alpha += 0.1;
                }
            }
        }
        tiao() {
            if (zhucaidan.tiao == 1) {
                Laya.Scene.open("guan1cj1.scene");
            }
            else if (zhucaidan.tiao == 2) {
                Laya.Scene.open("guan2cj1.scene");
            }
            else if (zhucaidan.tiao == 3) {
                Laya.Scene.open("guan3cj1.scene");
            }
            else if (zhucaidan.tiao == 4) {
                Laya.Scene.open("guan4cj1.scene");
            }
            else if (zhucaidan.tiao == 5) {
                Laya.Scene.open("guan5cj1.scene");
            }
        }
    }

