    class baoxiang extends Laya.Script {
        constructor() { super(); }
        onEnable() {
            this.kg = true;
            this.qy = this.owner.getChildByName("qy");
            this.dz = 1;
            this.owner.stop();
            this.owner.alpha = 0;
            this.owner.on(Laya.Event.COMPLETE, this, this.sanhanshu);
        }
        onUpdate() {
            this.owner.zOrder = this.owner.y;
            if (this.dz == 1) {
                if (this.owner.index == 10) {
                    Laya.SoundManager.playSound("sound/diao.wav");
                }
            }
            if (this.dz == 2) {
                if (this.kg == true) {
                    if (this.qy.hitTestPoint(zhucaidan.p1.x, zhucaidan.p1.y) || this.qy.hitTestPoint(zhucaidan.p2.x, zhucaidan.p2.y)) {
                        this.owner.play(0, true, "kai");
                        this.owner.frameOnce(10, this, this.sy);
                        this.kg = false;
                    }
                }
                if (this.owner.index == 26) {
                    let wp = Laya.Pool.getItemByCreateFun("wp", this.wuping.create, this.wuping);
                    wp.pos(this.owner.x, this.owner.y);
                    zhucaidan.p1.scene.addChild(wp);
                    this.owner.play(this.owner.index + 1);
                }
            }
        }
        sy() {
            Laya.SoundManager.playSound("sound/dakai.wav");
        }
        sanhanshu() {
            if (this.dz == 1) {
                this.owner.play(0, true, "zhanli");
                this.dz = 2;
            }
            if (this.dz == 2 && this.kg == false) {
                this.owner.destroy();
            }
        }
    }

