        onKeyUp(an) {
            if (zhucaidan.p1.skewX == 0) {
                if (this.p1dz == "zoulu") {
                    if (this.anshangkg == false && this.anxiakg == false) {
                        if (an.keyCode == 65 || an.keyCode == 68) {
                            this.p1.play(0, true, "zhanli");
                            this.p1dz = "zhanli";
                        }
                    }
                    if (this.anzuokg == false && this.anyoukg == false) {
                        if (an.keyCode == 87 || an.keyCode == 83) {
                            this.p1.play(0, true, "zhanli");
                            this.p1dz = "zhanli";
                        }
                    }
                }
                if (an.keyCode == 65) {
                    this.anzuokg = false;
                }
                if (an.keyCode == 68) {
                    this.anyoukg = false;
                }
                if (an.keyCode == 87) {
                    this.anshangkg = false;
                }
                if (an.keyCode == 83) {
                    this.anxiakg = false;
                }
            }
            if (zhucaidan.p2.skewX == 0) {
                if (this.p2dz == "zoulu") {
                    if (this.anzuokg2 == false && this.anyoukg2 == false) {
                        if (an.keyCode == 38 || an.keyCode == 40) {
                            this.p2.play(0, true, "zhanli");
                            this.p2dz = "zhanli";
                        }
                    }
                    if (this.anshangkg2 == false && this.anxiakg2 == false) {
                        if (an.keyCode == 37 || an.keyCode == 39) {
                            this.p2.play(0, true, "zhanli");
                            this.p2dz = "zhanli";
                        }
                    }
                }
                if (an.keyCode == 37) {
                    this.anzuokg2 = false;
                }
                if (an.keyCode == 38) {
                    this.anshangkg2 = false;
                }
                if (an.keyCode == 39) {
                    this.anyoukg2 = false;
                }
                if (an.keyCode == 40) {
                    this.anxiakg2 = false;
                }
            }
        }
