    class xiaoditu extends Laya.Script {
        constructor() {
            super();
            this.intType = 1000;
            this.numType = 1000;
            this.strType = "hello laya";
            this.boolType = true;
        }
        onEnable() {
            this.xiaoditu = this.owner.getChildByName("xiaoditu");
            this.xiaoren = this.owner.getChildByName("xiaoren");
            this.an = this.owner.getChildByName("an");
            this.an.on(Laya.Event.CLICK, this, this.anhanshu);
            if (zhucaidan.xiaoditux == true) {
                this.xiaoditu.visible = true;
                this.xiaoren.visible = true;
            }
            else if (zhucaidan.xiaoditux == false) {
                this.xiaoditu.visible = false;
                this.xiaoren.visible = false;
            }
            if (zhucaidan.moshi == 3 || zhucaidan.moshi == 4) {
                this.owner.visible = false;
            }
        }
        anhanshu() {
            if (this.xiaoditu.visible == true && this.xiaoren.visible == true) {
                this.xiaoditu.visible = false;
                this.xiaoren.visible = false;
                zhucaidan.xiaoditux = false;
            }
            else if (this.xiaoditu.visible == false && this.xiaoren.visible == false) {
                this.xiaoditu.visible = true;
                this.xiaoren.visible = true;
                zhucaidan.xiaoditux = true;
            }
        }
    }

    class diren1 extends Laya.Script {
        constructor() { super(); }
        onEnable() {
            this.sh = 5;
            this.speed = 2;
            this.xuetiao = this.owner.getChildByName("xuetiao");
            this.qy = this.owner.getChildByName("qy");
            this.owner.play(0, true, "zhanli");
            this.owner.on(Laya.Event.COMPLETE, this, this.dzhanshu);
        }
        dzhanshu() {
            this.owner.skewX = 0;
            this.suiji = Math.round(Math.random() * 10);
            if (this.suiji <= 3) {
                this.owner.play(0, true, "zhanli");
                this.dz = 1;
            }
            if (this.suiji > 3 && this.suiji <= 6) {
                this.owner.play(0, true, "zouqian");
                this.dz = 2;
            }
            if (this.suiji == 7 || this.suiji == 8) {
                this.owner.play(0, true, "zouhou");
                this.dz = 3;
            }
            if (this.suiji == 9 || this.suiji == 10) {
                this.owner.play(0, true, "gongji");
                this.dz = 4;
            }
        }
        onUpdate() {
            this.owner.zOrder = this.owner.y;
            if (this.owner.skewX == 0) {
                if (this.dz == 2) {
                    if (this.owner.x > zhucaidan.p1.x + 10) {
                        this.owner.scaleX = 1;
                        this.owner.x -= this.speed;
                    }
                    if (this.owner.x < zhucaidan.p1.x - 10) {
                        this.owner.scaleX = -1;
                        this.owner.x += this.speed;
                    }
                    if (this.owner.y < zhucaidan.p1.y - 2) {
                        this.owner.y += this.speed - 1;
                    }
                    if (this.owner.y > zhucaidan.p1.y + 2) {
                        this.owner.y -= this.speed - 1;
                    }
                }
                if (this.dz == 3) {
                    if (this.owner.x > zhucaidan.p1.x + 10) {
                        this.owner.scaleX = 1;
                        this.owner.x += this.speed;
                    }
                    if (this.owner.x < zhucaidan.p1.x - 10) {
                        this.owner.scaleX = -1;
                        this.owner.x -= this.speed;
                    }
                }
                if (this.dz == 4) {
                    if (this.owner.index == 5) {
                        if (this.qy.hitTestPoint(zhucaidan.p1.x, zhucaidan.p1.y)) {
                            if (zhucaidan.p1.skewX == 0) {
                                zhucaidan.p1.play(0, true, "dafei");
                                zhucaidan.p1xue -= this.sh;
                                zhucaidan.p1.skewX = 0.1;
                            }
                        }
                        if (this.qy.hitTestPoint(zhucaidan.p2.x, zhucaidan.p2.y)) {
                            if (zhucaidan.p2.skewX == 0) {
                                zhucaidan.p2.play(0, true, "dafei");
                                zhucaidan.p2xue -= this.sh;
                                zhucaidan.p2.skewX = 0.1;
                            }
                        }
                    }
                }
            }
            if (this.owner.x < 0) {
                this.owner.x = 0;
            }
            if (this.owner.x > 800) {
                this.owner.x = 800;
            }
        }
    }

