    class gkzi extends Laya.Script {
        constructor() {
            super();
            this.intType = 1000;
            this.numType = 1000;
            this.strType = "hello laya";
            this.boolType = true;
        }
        onEnable() {
            this.time = 0;
            this.owner.alpha = 0;
            if (zhucaidan.moshi == 3 || zhucaidan.moshi == 4) {
                this.owner.removeSelf();
            }
            this.owner.zOrder = 1000;
            if (zhucaidan.gkzikg == false) {
                this.owner.removeSelf();
            }
        }
        onUpdate() {
            this.time++;
            if (this.time >= 5 && this.time <= 30) {
                if (this.owner.alpha < 1) {
                    this.owner.alpha += 0.04;
                }
            }
            if (this.time >= 120) {
                this.owner.alpha -= 0.02;
                if (this.owner.alpha <= 0) {
                    zhucaidan.gkzikg = false;
                    this.owner.destroy();
                }
            }
        }
    }

