    class diren7 extends Laya.Script {
        constructor() { super(); }
        onEnable() {
            this.sh = 10;
            this.speed = 3;
            this.xuetiao = this.owner.getChildByName("xuetiao");
            this.qy = this.owner.getChildByName("qy");
            this.owner.play(0, true, "zhanli");
            this.owner.on(Laya.Event.COMPLETE, this, this.dzhanshu);
        }
        dzhanshu() {
            this.owner.skewX = 0;
            this.suiji = Math.round(Math.random() * 10);
            if (this.suiji <= 3) {
                this.owner.play(0, true, "zhanli");
                this.dz = 1;
            }
            if (this.suiji > 3 && this.suiji <= 6) {
                this.owner.play(0, true, "zouqian");
                this.dz = 2;
            }
            if (this.suiji == 7 || this.suiji == 8) {
                this.owner.play(0, true, "zouhou");
                this.dz = 3;
            }
            if (this.suiji == 9 || this.suiji == 10) {
                this.owner.play(0, true, "gongji");
                this.dz = 4;
            }
        }
        onUpdate() {
            this.owner.zOrder = this.owner.y;
            if (this.owner.skewX == 0) {
                if (this.dz == 2) {
                    if (this.owner.x > zhucaidan.p1.x + 10) {
                        this.owner.scaleX = 1;
                        this.owner.x -= this.speed;
                    }
                    if (this.owner.x < zhucaidan.p1.x - 10) {
                        this.owner.scaleX = -1;
                        this.owner.x += this.speed;
                    }
                    if (this.owner.y < zhucaidan.p1.y - 2) {
                        this.owner.y += this.speed - 1;
                    }
                    if (this.owner.y > zhucaidan.p1.y + 2) {
                        this.owner.y -= this.speed - 1;
                    }
                }
                if (this.dz == 3) {
                    if (this.owner.x > zhucaidan.p1.x + 10) {
                        this.owner.scaleX = 1;
                        this.owner.x += this.speed;
                    }
                    if (this.owner.x < zhucaidan.p1.x - 10) {
                        this.owner.scaleX = -1;
                        this.owner.x -= this.speed;
                    }
                }
                if (this.dz == 4) {
                    if (this.owner.index == 15) {
                        if (this.qy.hitTestPoint(zhucaidan.p1.x, zhucaidan.p1.y)) {
                            if (zhucaidan.p1.skewX == 0) {
                                zhucaidan.p1.play(0, true, "dafei");
                                zhucaidan.p1xue -= this.sh;
                                zhucaidan.p1.skewX = 0.1;
                            }
                        }
                        if (this.qy.hitTestPoint(zhucaidan.p2.x, zhucaidan.p2.y)) {
                            if (zhucaidan.p2.skewX == 0) {
                                zhucaidan.p2.play(0, true, "dafei");
                                zhucaidan.p2xue -= this.sh;
                                zhucaidan.p2.skewX = 0.1;
                            }
                        }
                    }
                }
            }
            if (this.owner.x < 0) {
                this.owner.x = 0;
            }
            if (this.owner.x > 800) {
                this.owner.x = 800;
            }
        }
    }

