    class kaishi extends Laya.Script {
        constructor() {
            super();
            this.intType = 1000;
            this.numType = 1000;
            this.strType = "hello laya";
            this.boolType = true;
        }
        onEnable() {
            this.kg = true;
            this.zc = this.owner.getChildByName("zc");
            this.zc.on(Laya.Event.CLICK, this, this.zchanshu);
            this.zc.on(Laya.Event.COMPLETE, this, this.tiaohanshu);
            this.quan = this.owner.getChildByName("quan");
            this.quan.on(Laya.Event.COMPLETE, this, this.quanhanshu);
        }
        zchanshu() {
            this.zc.play();
        }
        tiaohanshu() {
            Laya.Scene.open("zhucaidan.scene");
        }
        onMouseDown() {
            if (this.kg == true) {
                Laya.SoundManager.playSound("sound/dianji.wav");
                this.quan.pos(Laya.stage.mouseX, Laya.stage.mouseY);
                this.quan.play();
                this.kg = false;
            }
        }
        quanhanshu() {
            this.quan.gotoAndStop(this.quan.count);
        }
    }

