    class zidan1 extends Laya.Script {
        constructor() { super(); }
        onEnable() {
            this.time = 70;
            this.jitui = 20;
            this.kg = true;
            this.qy = this.owner.getChildByName("qy");
        }
        onUpdate() {
            if (this.owner.scaleX == 1) {
                this.owner.x += this.speed;
            }
            else if (this.owner.scaleX == -1) {
                this.owner.x -= this.speed;
            }
            this.time--;
            if (this.kg == true) {
                for (this.i = 1; this.i < 11; this.i++) {
                    if (this.qy.hitTestPoint(zhucaidan["diren" + this.i].x, zhucaidan["diren" + this.i].y)) {
                        if (zhucaidan["diren" + this.i].destroyed == false) {
                            zhucaidan["diren" + this.i].play(0, true, "ss");
                            if (zhucaidan["diren" + this.i].scaleX > 0) {
                                zhucaidan["diren" + this.i].x += this.jitui;
                            }
                            else if (zhucaidan["diren" + this.i].scaleX < 0) {
                                zhucaidan["diren" + this.i].x -= this.jitui;
                            }
                            zhucaidan["diren" + this.i].skewX = 1;
                            let bz = Laya.Pool.getItemByCreateFun("bz", this.baozha.create, this.baozha);
                            bz.pos(zhucaidan["diren" + this.i].x, zhucaidan["diren" + this.i].y - 70);
                            bz.play();
                            Laya.stage.addChild(bz);
                            zhucaidan["diren" + this.i + "xue"] -= this.sh;
                            if (this.sy == 1) {
                                Laya.SoundManager.playSound("sound/mingzhong1.wav");
                            }
                            if (this.sy == 2) {
                                Laya.SoundManager.playSound("sound/mingzhong2.wav");
                            }
                            if (this.sy == 3) {
                                Laya.SoundManager.playSound("sound/baozha.wav");
                            }
                            if (this.sy == 4) {
                                Laya.SoundManager.playSound("sound/baozha2.wav");
                            }
                            if (this.sy == 5) {
                                Laya.SoundManager.playSound("sound/huoquan.wav");
                            }
                            if (this.sy == 6) {
                                Laya.SoundManager.playSound("sound/dianmingzhong.wav");
                            }
                            this.kg = false;
                            this.owner.frameOnce(1, this, this.sanhanshu);
                        }
                    }
                }
            }
            if (this.time < 0) {
                this.sanhanshu();
            }
        }
        sanhanshu() {
            this.owner.destroy();
        }
    }

